import React, { useEffect, useRef, useState } from 'react'
import SensorVisualization from './SensorVisualization'
import { generateSensorSnapshot } from '../utils/dataGenerator'
import './PartnerNode.css'

function PartnerNode({ partner, isSelected, onSelect }) {
  const [sensorData, setSensorData] = useState(null)
  const [privacyLevel, setPrivacyLevel] = useState('encrypted')
  const intervalRef = useRef(null)

  useEffect(() => {
    // Generate sensor data updates
    const updateSensorData = () => {
      const data = generateSensorSnapshot(Date.now(), partner.id)
      setSensorData(data)
    }

    updateSensorData()
    intervalRef.current = setInterval(updateSensorData, 1000)

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
      }
    }
  }, [partner.id])

  const getPartnerIcon = (type) => {
    switch (type) {
      case 'oem':
        return '🚛'
      case 'supplier':
        return '🏭'
      case 'academic':
        return '🎓'
      default:
        return '🏢'
    }
  }

  const formatDataCount = (count) => {
    if (count >= 1000) return `${(count / 1000).toFixed(1)}K`
    return count.toString()
  }

  return (
    <div
      className={`partner-node ${isSelected ? 'selected' : ''} ${
        partner.isTraining ? 'training' : ''
      }`}
      style={{ '--partner-color': partner.color }}
      onClick={onSelect}
    >
      {/* Header */}
      <div className="partner-header">
        <div className="partner-info">
          <span className="partner-icon">{getPartnerIcon(partner.type)}</span>
          <div>
            <h3 className="partner-name">{partner.name}</h3>
            <span className="partner-status">
              {partner.isTraining ? (
                <>
                  <span className="status-dot training" />
                  Training...
                </>
              ) : (
                <>
                  <span className="status-dot" />
                  Ready
                </>
              )}
            </span>
          </div>
        </div>

        {/* Privacy Badge */}
        <div className="privacy-badge">
          <span className="privacy-icon">🔒</span>
          <span className="privacy-text">Private</span>
        </div>
      </div>

      {/* Sensor Visualization */}
      <div className="sensor-viz-container">
        {sensorData && (
          <SensorVisualization
            sensorData={sensorData}
            partnerId={partner.id}
            privacyLevel={privacyLevel}
            color={partner.color}
          />
        )}

        {/* Privacy Overlay */}
        {privacyLevel === 'encrypted' && (
          <div className="privacy-overlay">
            <div className="privacy-message">
              <span className="lock-icon">🔐</span>
              <p>Raw data stays on-premises</p>
              <small>Only encrypted gradients are shared</small>
            </div>
          </div>
        )}
      </div>

      {/* Metrics */}
      <div className="partner-metrics">
        <div className="metric">
          <span className="metric-label">Local Accuracy</span>
          <span className="metric-value">
            {(partner.localAccuracy * 100).toFixed(1)}%
          </span>
        </div>

        <div className="metric">
          <span className="metric-label">Data Samples</span>
          <span className="metric-value">{formatDataCount(partner.dataCount)}</span>
        </div>

        <div className="metric">
          <span className="metric-label">Privacy</span>
          <span className="metric-value privacy-enabled">ε=0.1</span>
        </div>
      </div>

      {/* Privacy Control */}
      <div className="privacy-control">
        <label>
          <input
            type="checkbox"
            checked={privacyLevel === 'visible'}
            onChange={(e) =>
              setPrivacyLevel(e.target.checked ? 'visible' : 'encrypted')
            }
            onClick={(e) => e.stopPropagation()}
          />
          <span>Show raw data (demo only)</span>
        </label>
      </div>

      {/* Training Indicator */}
      {partner.isTraining && (
        <div className="training-indicator">
          <div className="training-bar" />
        </div>
      )}
    </div>
  )
}

export default PartnerNode
