/**
 * Synthetic Sensor Data Generator
 * Simulates multimodal sensor data from autonomous vehicle environments
 */

// Generate synthetic LiDAR point cloud
export function generateLiDARPointCloud(timestamp, seed = 0) {
  const points = [];
  const numPoints = 2000;
  const t = timestamp / 1000;

  for (let i = 0; i < numPoints; i++) {
    const angle = (i / numPoints) * Math.PI * 2 + seed;
    const distance = 5 + Math.sin(angle * 3 + t) * 2 + Math.random() * 0.5;
    const height = Math.sin(angle * 5 + seed) * 1.5 + Math.random() * 0.3;

    const x = Math.cos(angle) * distance;
    const y = height;
    const z = Math.sin(angle) * distance;
    const intensity = Math.random() * 255;

    points.push({ x, y, z, intensity });
  }

  return points;
}

// Generate synthetic camera image features
export function generateCameraFeatures(timestamp, seed = 0) {
  const features = [];
  const numFeatures = 50;
  const t = timestamp / 1000;

  for (let i = 0; i < numFeatures; i++) {
    const x = (Math.sin(i + t + seed) * 0.5 + 0.5) * 640;
    const y = (Math.cos(i * 2 + t + seed) * 0.5 + 0.5) * 480;
    const confidence = 0.7 + Math.random() * 0.3;
    const label = ['pedestrian', 'vehicle', 'cyclist', 'sign'][Math.floor(Math.random() * 4)];

    features.push({ x, y, confidence, label });
  }

  return features;
}

// Generate synthetic IMU data (accelerometer + gyroscope)
export function generateIMUData(timestamp, seed = 0) {
  const t = timestamp / 1000;
  const noise = () => (Math.random() - 0.5) * 0.1;

  return {
    accelerometer: {
      x: Math.sin(t * 2 + seed) * 0.5 + noise(),
      y: Math.cos(t * 1.5 + seed) * 0.3 + noise(),
      z: 9.81 + Math.sin(t * 3 + seed) * 0.2 + noise(), // Gravity + vehicle motion
    },
    gyroscope: {
      x: Math.sin(t * 1.2 + seed) * 0.1 + noise(),
      y: Math.cos(t * 0.8 + seed) * 0.15 + noise(),
      z: Math.sin(t * 1.5 + seed) * 0.2 + noise(),
    },
    timestamp,
  };
}

// Generate synthetic tactile sensor data (from Delby smart glove)
export function generateTactileData(timestamp, seed = 0) {
  const t = timestamp / 1000;
  const sensors = [];

  // 16 pressure sensors in a 4x4 grid on the glove palm
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      const baseVal = Math.sin(t + seed + i * j) * 50 + 50;
      const pressure = Math.max(0, baseVal + (Math.random() - 0.5) * 20);
      sensors.push({
        x: i,
        y: j,
        pressure,
        temperature: 22 + Math.random() * 3, // Celsius
      });
    }
  }

  return { sensors, timestamp };
}

// Generate complete multimodal sensor snapshot
export function generateSensorSnapshot(timestamp, partnerId) {
  const seed = partnerId * 100; // Different patterns for different partners

  return {
    timestamp,
    partnerId,
    lidar: generateLiDARPointCloud(timestamp, seed),
    camera: generateCameraFeatures(timestamp, seed),
    imu: generateIMUData(timestamp, seed),
    tactile: generateTactileData(timestamp, seed),
  };
}

// Simulate behavior labels for supervised learning
export function generateBehaviorLabel(sensorData) {
  const behaviors = [
    'normal_driving',
    'hard_braking',
    'sharp_turn',
    'lane_change',
    'pedestrian_detection',
    'obstacle_avoidance',
  ];

  // Deterministic based on sensor patterns
  const imu = sensorData.imu;
  const accelMag = Math.sqrt(
    imu.accelerometer.x ** 2 +
    imu.accelerometer.y ** 2 +
    (imu.accelerometer.z - 9.81) ** 2
  );
  const gyroMag = Math.sqrt(
    imu.gyroscope.x ** 2 +
    imu.gyroscope.y ** 2 +
    imu.gyroscope.z ** 2
  );

  let behaviorIdx = 0;
  if (accelMag > 1.5) behaviorIdx = 1; // hard_braking
  else if (gyroMag > 0.3) behaviorIdx = 2; // sharp_turn
  else if (sensorData.camera.some(f => f.label === 'pedestrian')) behaviorIdx = 4;

  return {
    label: behaviors[behaviorIdx],
    confidence: 0.7 + Math.random() * 0.3,
  };
}

// Generate training batch
export function generateTrainingBatch(partnerId, batchSize = 8) {
  const batch = [];
  const now = Date.now();

  for (let i = 0; i < batchSize; i++) {
    const timestamp = now + i * 100;
    const sensorData = generateSensorSnapshot(timestamp, partnerId);
    const label = generateBehaviorLabel(sensorData);

    batch.push({
      input: sensorData,
      label: label.label,
      confidence: label.confidence,
    });
  }

  return batch;
}
