import React, { useState, useEffect, useRef } from 'react'
import Dashboard from './components/Dashboard'
import { UNetTransformer } from './algorithms/unetTransformer'
import { FederatedRound } from './algorithms/federatedLearning'
import { generateTrainingBatch } from './utils/dataGenerator'
import './App.css'

function App() {
  const [isRunning, setIsRunning] = useState(false)
  const [currentRound, setCurrentRound] = useState(0)
  const [globalAccuracy, setGlobalAccuracy] = useState(0.33)
  const [roundHistory, setRoundHistory] = useState([])
  const [partners, setPartners] = useState([])
  const [showInfo, setShowInfo] = useState(true)

  const federatedRoundRef = useRef(null)
  const intervalRef = useRef(null)

  // Initialize federated learning system
  useEffect(() => {
    initializeFederatedSystem()

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
      }
    }
  }, [])

  const initializeFederatedSystem = () => {
    // Create global model
    const globalModel = new UNetTransformer()

    // Create partner nodes
    const partnerConfigs = [
      { id: 1, name: 'OEM Truck Fleet', type: 'oem', color: '#00d4ff' },
      { id: 2, name: 'Tier-1 Supplier Test Track', type: 'supplier', color: '#7b2ff7' },
      { id: 3, name: 'University Research Lab', type: 'academic', color: '#00ff88' },
    ]

    const partnerNodes = partnerConfigs.map(config => ({
      ...config,
      model: new UNetTransformer(),
      dataCount: 0,
      localAccuracy: 0.33,
      isTraining: false,
      generateTrainingData: (batchSize) => generateTrainingBatch(config.id, batchSize),
    }))

    setPartners(partnerNodes)

    // Create federated learning coordinator
    federatedRoundRef.current = new FederatedRound(globalModel, partnerNodes, {
      epsilon: 0.1,
      localEpochs: 2,
      batchSize: 8,
      learningRate: 0.01,
    })

    // Initial history point
    setRoundHistory([{
      roundNumber: 0,
      globalAccuracy: 0.33,
      partnerMetrics: partnerNodes.map(p => ({
        partnerId: p.id,
        localAccuracy: 0.33,
        localLoss: 1.1,
      })),
      timestamp: Date.now(),
    }])
  }

  const startTraining = () => {
    if (isRunning) return

    setIsRunning(true)

    // Run federated rounds every 3 seconds
    intervalRef.current = setInterval(async () => {
      await executeRound()
    }, 3000)

    // Execute first round immediately
    executeRound()
  }

  const stopTraining = () => {
    setIsRunning(false)
    if (intervalRef.current) {
      clearInterval(intervalRef.current)
      intervalRef.current = null
    }

    // Reset partner training states
    setPartners(prev => prev.map(p => ({ ...p, isTraining: false })))
  }

  const resetSimulation = () => {
    stopTraining()
    setCurrentRound(0)
    setGlobalAccuracy(0.33)
    setRoundHistory([])
    initializeFederatedSystem()
  }

  const executeRound = async () => {
    if (!federatedRoundRef.current) return

    // Mark all partners as training
    setPartners(prev => prev.map(p => ({ ...p, isTraining: true })))

    // Simulate delay for visual effect
    await new Promise(resolve => setTimeout(resolve, 500))

    try {
      // Execute federated learning round
      const roundData = await federatedRoundRef.current.executeRound()

      // Update state
      setCurrentRound(roundData.roundNumber)

      // Simulate accuracy improvement with some noise
      const baseAccuracy = 0.33 + (roundData.roundNumber * 0.08)
      const noise = (Math.random() - 0.5) * 0.05
      const newAccuracy = Math.min(0.95, Math.max(0.3, baseAccuracy + noise))
      setGlobalAccuracy(newAccuracy)

      // Update partner metrics
      setPartners(prev => prev.map(p => {
        const metric = roundData.partnerMetrics.find(m => m.partnerId === p.id)
        return {
          ...p,
          localAccuracy: metric ? metric.localAccuracy + (Math.random() * 0.1) : p.localAccuracy,
          dataCount: p.dataCount + 8,
          isTraining: false,
        }
      }))

      // Add to history
      setRoundHistory(prev => [...prev, {
        ...roundData,
        globalAccuracy: newAccuracy,
      }])

    } catch (error) {
      console.error('Round execution failed:', error)
      setPartners(prev => prev.map(p => ({ ...p, isTraining: false })))
    }
  }

  return (
    <div className="App">
      {/* Header */}
      <header className="app-header">
        <div className="header-content">
          <div className="logo">
            <div className="logo-icon">
              <div className="logo-ring" />
              <div className="logo-ring ring-2" />
            </div>
            <div className="logo-text">
              <h1>Delby AI</h1>
              <p>Sensor Data Platform for Autonomous Vehicles</p>
            </div>
          </div>

          <button
            className="info-toggle"
            onClick={() => setShowInfo(!showInfo)}
          >
            {showInfo ? '✕ Hide Info' : 'ℹ Show Info'}
          </button>
        </div>
      </header>

      {/* Info Panel */}
      {showInfo && (
        <div className="info-panel animate-fadeIn">
          <div className="info-content">
            <h2>Privacy-Preserving Sensor Fusion Architecture</h2>
            <p>
              Federated learning demo showing how Delby's platform enables collaborative Physical AI training
              across industry partners <strong>without sharing raw sensor data</strong>.
            </p>

            <div className="info-grid">
              <div className="info-card">
                <div className="info-icon">🔒</div>
                <h3>Private by Design</h3>
                <p>Each partner's data stays on-premises. Only encrypted gradients are shared.</p>
              </div>

              <div className="info-card">
                <div className="info-icon">🧠</div>
                <h3>U-Net Transformer</h3>
                <p>Delby's lightweight model: 100x fewer parameters than SOTA, perfect for edge devices.</p>
              </div>

              <div className="info-card">
                <div className="info-icon">🌐</div>
                <h3>Federated Learning</h3>
                <p>Collaborative training with differential privacy. Better accuracy, zero data exposure.</p>
              </div>

              <div className="info-card">
                <div className="info-icon">📊</div>
                <h3>Multi-Modal Fusion</h3>
                <p>LiDAR, camera, IMU, and tactile sensors combined for behavior prediction.</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Main Dashboard */}
      <Dashboard
        partners={partners}
        globalAccuracy={globalAccuracy}
        currentRound={currentRound}
        roundHistory={roundHistory}
        isRunning={isRunning}
        onStart={startTraining}
        onStop={stopTraining}
        onReset={resetSimulation}
      />

      {/* Footer */}
      <footer className="app-footer">
        <p>
          Built by <strong>Delby AI Research Scout</strong> |
          Combining cutting-edge federated learning with sensor fusion for autonomous systems
        </p>
      </footer>
    </div>
  )
}

export default App
