/**
 * Federated Learning Algorithms
 * Implements FedAvg, differential privacy, and secure aggregation
 */

// Differential Privacy: Add Laplace noise to gradients
export function addDifferentialPrivacy(gradients, epsilon = 0.1, sensitivity = 1.0) {
  const scale = sensitivity / epsilon;

  // Laplace noise: sample from Laplace(0, scale)
  const laplaceNoise = () => {
    const u = Math.random() - 0.5;
    return -scale * Math.sign(u) * Math.log(1 - 2 * Math.abs(u));
  };

  const noisyGradients = gradients.map(g => ({
    ...g,
    gradients: g.gradients.map(val => val + laplaceNoise()),
  }));

  return noisyGradients;
}

// Simulate gradient encryption (simplified representation)
export function encryptGradients(gradients, publicKey) {
  // In real implementation: homomorphic encryption or secure multi-party computation
  // For demo: Add/multiply with key-derived values to show obfuscation
  const keyHash = hashString(publicKey);

  return gradients.map(g => ({
    encrypted: true,
    data: g.map((val, i) => val * (1 + (keyHash + i) / 10000) + (keyHash % 100) / 100),
    shape: g.length,
  }));
}

// Simulate gradient decryption
export function decryptGradients(encryptedGradients, privateKey) {
  const keyHash = hashString(privateKey);

  return encryptedGradients.map(eg => ({
    decrypted: true,
    data: eg.data.map((val, i) => (val - (keyHash % 100) / 100) / (1 + (keyHash + i) / 10000)),
  }));
}

// Simple hash function for demo
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash);
}

// Federated Averaging (FedAvg) - core algorithm
export function federatedAverage(partnerUpdates) {
  if (partnerUpdates.length === 0) return null;

  // Each update contains: { parameters, numSamples }
  const totalSamples = partnerUpdates.reduce((sum, update) => sum + update.numSamples, 0);

  // Initialize averaged parameters
  const avgParams = {
    encoder: new Array(partnerUpdates[0].parameters.encoder.length).fill(0),
    classifier: new Array(partnerUpdates[0].parameters.classifier.length).fill(0),
  };

  // Weighted average based on number of samples
  partnerUpdates.forEach(update => {
    const weight = update.numSamples / totalSamples;

    update.parameters.encoder.forEach((val, i) => {
      avgParams.encoder[i] += val * weight;
    });

    update.parameters.classifier.forEach((val, i) => {
      avgParams.classifier[i] += val * weight;
    });
  });

  return avgParams;
}

// Secure aggregation with differential privacy
export function secureAggregation(partnerGradients, epsilon = 0.1) {
  // Step 1: Add differential privacy noise at each partner
  const noisyGradients = partnerGradients.map(pg => ({
    partnerId: pg.partnerId,
    gradients: pg.gradients.map(g => g + (Math.random() - 0.5) * (2 / epsilon)),
    numSamples: pg.numSamples,
  }));

  // Step 2: Aggregate (average)
  const totalSamples = noisyGradients.reduce((sum, ng) => sum + ng.numSamples, 0);

  const aggregatedGradients = new Array(noisyGradients[0].gradients.length).fill(0);

  noisyGradients.forEach(ng => {
    const weight = ng.numSamples / totalSamples;
    ng.gradients.forEach((g, i) => {
      aggregatedGradients[i] += g * weight;
    });
  });

  return {
    aggregatedGradients,
    privacyBudget: epsilon,
    numPartners: noisyGradients.length,
    totalSamples,
  };
}

// Compute model accuracy on test set
export function computeAccuracy(model, testData) {
  let correct = 0;
  const predictions = [];

  testData.forEach(sample => {
    const prediction = model.predict(sample.input);
    const isCorrect = prediction.prediction === sample.label;
    if (isCorrect) correct++;

    predictions.push({
      input: sample.input,
      predicted: prediction.prediction,
      actual: sample.label,
      confidence: prediction.confidence,
      correct: isCorrect,
    });
  });

  return {
    accuracy: correct / testData.length,
    correct,
    total: testData.length,
    predictions,
  };
}

// Federated Learning Round
export class FederatedRound {
  constructor(globalModel, partners, config = {}) {
    this.globalModel = globalModel;
    this.partners = partners; // Array of partner objects with local models
    this.config = {
      epsilon: config.epsilon || 0.1,
      localEpochs: config.localEpochs || 3,
      batchSize: config.batchSize || 8,
      learningRate: config.learningRate || 0.01,
      ...config,
    };
    this.roundNumber = 0;
    this.history = [];
  }

  // Execute one federated learning round
  async executeRound() {
    this.roundNumber++;
    const roundStart = Date.now();

    // Phase 1: Distribute global model to partners
    const globalParams = this.globalModel.getParameters();
    this.partners.forEach(partner => {
      partner.model.setParameters(globalParams);
    });

    // Phase 2: Local training at each partner
    const partnerUpdates = [];
    const partnerMetrics = [];

    for (const partner of this.partners) {
      const localResult = await this.localTraining(partner);
      partnerUpdates.push({
        partnerId: partner.id,
        parameters: localResult.parameters,
        gradients: localResult.gradients,
        numSamples: localResult.numSamples,
      });
      partnerMetrics.push({
        partnerId: partner.id,
        localLoss: localResult.loss,
        localAccuracy: localResult.accuracy,
      });
    }

    // Phase 3: Secure aggregation with differential privacy
    const aggregationResult = this.aggregateUpdates(partnerUpdates);

    // Phase 4: Update global model
    this.globalModel.setParameters(aggregationResult.parameters);

    // Phase 5: Evaluate global model
    const globalAccuracy = this.evaluateGlobalModel();

    const roundData = {
      roundNumber: this.roundNumber,
      duration: Date.now() - roundStart,
      partnerMetrics,
      globalAccuracy,
      privacyBudget: this.config.epsilon,
      timestamp: Date.now(),
    };

    this.history.push(roundData);

    return roundData;
  }

  // Local training at a single partner
  async localTraining(partner) {
    const trainingData = partner.generateTrainingData(this.config.batchSize);
    let totalLoss = 0;
    const gradients = [];

    // Train for multiple local epochs
    for (let epoch = 0; epoch < this.config.localEpochs; epoch++) {
      trainingData.forEach(sample => {
        const features = partner.model.constructor === Object
          ? sample.input
          : this.extractFeatures(sample.input);

        const labelIdx = this.getLabelIndex(sample.label);
        const result = partner.model.computeGradients(features, labelIdx);

        totalLoss += result.loss;
        gradients.push(result.gradients);

        // Apply gradient update locally
        partner.model.updateWeights(result.gradients, this.config.learningRate);
      });
    }

    // Compute local accuracy
    const accuracy = computeAccuracy(partner.model, trainingData);

    return {
      parameters: partner.model.getParameters(),
      gradients: gradients[gradients.length - 1] || [], // Last gradient
      loss: totalLoss / (trainingData.length * this.config.localEpochs),
      accuracy: accuracy.accuracy,
      numSamples: trainingData.length,
    };
  }

  // Aggregate updates from all partners
  aggregateUpdates(partnerUpdates) {
    // Apply differential privacy
    const noisyUpdates = partnerUpdates.map(update => ({
      ...update,
      gradients: update.gradients.map(g =>
        g + (Math.random() - 0.5) * (2 / this.config.epsilon)
      ),
    }));

    // Federated averaging
    const aggregatedParams = federatedAverage(noisyUpdates);

    return {
      parameters: aggregatedParams,
      numPartners: partnerUpdates.length,
      privacyBudget: this.config.epsilon,
    };
  }

  // Evaluate global model on test data
  evaluateGlobalModel() {
    let totalAccuracy = 0;

    this.partners.forEach(partner => {
      const testData = partner.generateTrainingData(4); // Small test set
      const tempModel = partner.model.constructor.name === 'UNetTransformer'
        ? partner.model
        : this.globalModel;

      // Set global parameters
      const originalParams = tempModel.getParameters();
      tempModel.setParameters(this.globalModel.getParameters());

      const accuracy = computeAccuracy(tempModel, testData);
      totalAccuracy += accuracy.accuracy;

      // Restore original parameters
      tempModel.setParameters(originalParams);
    });

    return totalAccuracy / this.partners.length;
  }

  extractFeatures(sensorData) {
    // Import needed, but for inline:
    return Object.values(sensorData).flat().slice(0, 64);
  }

  getLabelIndex(label) {
    const classes = [
      'normal_driving',
      'hard_braking',
      'sharp_turn',
      'lane_change',
      'pedestrian_detection',
      'obstacle_avoidance',
    ];
    return classes.indexOf(label);
  }

  getHistory() {
    return this.history;
  }

  getCurrentRound() {
    return this.roundNumber;
  }
}
