import React, { useState } from 'react'
import './QueryInterface.css'

const SAMPLE_QUERIES = [
  {
    query: 'pedestrian crossing during rain',
    description: 'Find scenarios with pedestrian detection in wet conditions',
  },
  {
    query: 'hard braking on highway',
    description: 'Emergency braking events at high speed',
  },
  {
    query: 'sharp turn with high load',
    description: 'Turning maneuvers under heavy vehicle load',
  },
]

function QueryInterface({ partners, onClose }) {
  const [searchQuery, setSearchQuery] = useState('')
  const [results, setResults] = useState(null)
  const [isSearching, setIsSearching] = useState(false)

  const handleSearch = () => {
    setIsSearching(true)

    // Simulate search delay
    setTimeout(() => {
      const mockResults = partners.map((partner) => ({
        partnerId: partner.id,
        partnerName: partner.name,
        matchCount: Math.floor(Math.random() * 50) + 10,
        matches: Array(3)
          .fill(null)
          .map((_, i) => ({
            id: `${partner.id}-${i}`,
            timestamp: Date.now() - Math.random() * 86400000,
            scenario: searchQuery || 'Sample scenario',
            confidence: 0.7 + Math.random() * 0.3,
            metadata: {
              location: ['Test Track', 'Highway I-80', 'Urban Area'][
                Math.floor(Math.random() * 3)
              ],
              weather: ['Clear', 'Rain', 'Snow'][Math.floor(Math.random() * 3)],
              timeOfDay: ['Morning', 'Afternoon', 'Night'][Math.floor(Math.random() * 3)],
            },
          })),
      }))

      setResults(mockResults)
      setIsSearching(false)
    }, 1500)
  }

  const handleSampleQuery = (query) => {
    setSearchQuery(query)
  }

  const formatTimestamp = (timestamp) => {
    return new Date(timestamp).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    })
  }

  return (
    <div className="query-interface-overlay" onClick={onClose}>
      <div className="query-interface" onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="query-header">
          <div>
            <h2>Privacy-Preserving Data Query</h2>
            <p>Search across all partners without accessing raw sensor data</p>
          </div>
          <button className="close-btn" onClick={onClose}>
            ✕
          </button>
        </div>

        {/* Search Bar */}
        <div className="search-section">
          <div className="search-bar">
            <span className="search-icon">🔍</span>
            <input
              type="text"
              placeholder="Search scenarios: e.g., 'pedestrian crossing during rain'"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
            />
            <button
              className="search-btn"
              onClick={handleSearch}
              disabled={!searchQuery || isSearching}
            >
              {isSearching ? 'Searching...' : 'Search'}
            </button>
          </div>

          {/* Sample Queries */}
          <div className="sample-queries">
            <span className="sample-label">Try:</span>
            {SAMPLE_QUERIES.map((sample, i) => (
              <button
                key={i}
                className="sample-query-btn"
                onClick={() => handleSampleQuery(sample.query)}
                title={sample.description}
              >
                {sample.query}
              </button>
            ))}
          </div>
        </div>

        {/* How It Works */}
        <div className="how-it-works">
          <h3>🔐 How Privacy-Preserving Query Works</h3>
          <div className="steps">
            <div className="step">
              <span className="step-num">1</span>
              <p>Query is encrypted and sent to all partners</p>
            </div>
            <div className="step">
              <span className="step-num">2</span>
              <p>Each partner searches their local data</p>
            </div>
            <div className="step">
              <span className="step-num">3</span>
              <p>Only metadata and counts are returned</p>
            </div>
            <div className="step">
              <span className="step-num">4</span>
              <p>Raw footage requires explicit permission</p>
            </div>
          </div>
        </div>

        {/* Results */}
        {results && (
          <div className="search-results">
            <div className="results-header">
              <h3>Search Results</h3>
              <span className="results-count">
                Found{' '}
                {results.reduce((sum, r) => sum + r.matchCount, 0)} matches
                across {results.length} partners
              </span>
            </div>

            {results.map((result) => (
              <div key={result.partnerId} className="result-partner">
                <div className="result-partner-header">
                  <h4>{result.partnerName}</h4>
                  <span className="match-count">
                    {result.matchCount} matches
                  </span>
                </div>

                <div className="result-matches">
                  {result.matches.map((match) => (
                    <div key={match.id} className="result-match">
                      <div className="match-info">
                        <div className="match-meta">
                          <span className="match-timestamp">
                            📅 {formatTimestamp(match.timestamp)}
                          </span>
                          <span className="match-location">
                            📍 {match.metadata.location}
                          </span>
                          <span className="match-weather">
                            🌤️ {match.metadata.weather}
                          </span>
                          <span className="match-time">
                            🕐 {match.metadata.timeOfDay}
                          </span>
                        </div>
                        <div className="match-confidence">
                          <div className="confidence-bar">
                            <div
                              className="confidence-fill"
                              style={{
                                width: `${match.confidence * 100}%`,
                              }}
                            />
                          </div>
                          <span className="confidence-label">
                            {(match.confidence * 100).toFixed(0)}% match
                          </span>
                        </div>
                      </div>

                      <button className="request-access-btn">
                        🔓 Request Raw Data Access
                      </button>
                    </div>
                  ))}
                </div>

                <button className="show-more-btn">
                  Show {result.matchCount - 3} more results
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Loading State */}
        {isSearching && (
          <div className="searching-state">
            <div className="searching-spinner" />
            <p>Securely querying all partners...</p>
          </div>
        )}
      </div>
    </div>
  )
}

export default QueryInterface
