import React, { useState } from 'react'
import PartnerNode from './PartnerNode'
import CentralServer from './CentralServer'
import ModelMetrics from './ModelMetrics'
import QueryInterface from './QueryInterface'
import ControlPanel from './ControlPanel'
import './Dashboard.css'

function Dashboard({
  partners,
  globalAccuracy,
  currentRound,
  roundHistory,
  isRunning,
  onStart,
  onStop,
  onReset,
}) {
  const [selectedPartner, setSelectedPartner] = useState(null)
  const [showQuery, setShowQuery] = useState(false)

  return (
    <div className="dashboard">
      <div className="dashboard-container">
        {/* Control Panel */}
        <ControlPanel
          isRunning={isRunning}
          currentRound={currentRound}
          globalAccuracy={globalAccuracy}
          onStart={onStart}
          onStop={onStop}
          onReset={onReset}
          onToggleQuery={() => setShowQuery(!showQuery)}
        />

        {/* Main Grid */}
        <div className="dashboard-grid">
          {/* Partner Nodes */}
          <div className="partners-section">
            <h2 className="section-title">
              <span className="title-icon">🏢</span>
              Partner Nodes
            </h2>
            <div className="partners-grid">
              {partners.map(partner => (
                <PartnerNode
                  key={partner.id}
                  partner={partner}
                  isSelected={selectedPartner === partner.id}
                  onSelect={() => setSelectedPartner(
                    selectedPartner === partner.id ? null : partner.id
                  )}
                />
              ))}
            </div>
          </div>

          {/* Central Server */}
          <div className="central-section">
            <h2 className="section-title">
              <span className="title-icon">☁️</span>
              Delby Cloud - Federated Aggregation
            </h2>
            <CentralServer
              partners={partners}
              globalAccuracy={globalAccuracy}
              currentRound={currentRound}
              isRunning={isRunning}
            />
          </div>

          {/* Metrics */}
          <div className="metrics-section">
            <h2 className="section-title">
              <span className="title-icon">📊</span>
              Global Model Performance
            </h2>
            <ModelMetrics
              roundHistory={roundHistory}
              currentRound={currentRound}
              globalAccuracy={globalAccuracy}
            />
          </div>
        </div>

        {/* Query Interface (Modal) */}
        {showQuery && (
          <QueryInterface
            partners={partners}
            onClose={() => setShowQuery(false)}
          />
        )}
      </div>
    </div>
  )
}

export default Dashboard
