import React, { useRef } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import { OrbitControls } from '@react-three/drei'
import * as THREE from 'three'
import './CentralServer.css'

function ServerCore({ isRunning }) {
  const coreRef = useRef()
  const ringsRef = useRef([])

  useFrame((state) => {
    if (coreRef.current) {
      coreRef.current.rotation.y += 0.01
      if (isRunning) {
        const scale = 1 + Math.sin(state.clock.elapsedTime * 2) * 0.1
        coreRef.current.scale.set(scale, scale, scale)
      }
    }

    ringsRef.current.forEach((ring, i) => {
      if (ring) {
        ring.rotation.x += 0.005 * (i + 1)
        ring.rotation.y += 0.003 * (i + 1)
      }
    })
  })

  return (
    <group>
      {/* Core */}
      <mesh ref={coreRef}>
        <icosahedronGeometry args={[1, 1]} />
        <meshStandardMaterial
          color="#00d4ff"
          emissive="#00d4ff"
          emissiveIntensity={isRunning ? 0.8 : 0.3}
          wireframe
        />
      </mesh>

      {/* Rings */}
      {[1.5, 2, 2.5].map((radius, i) => (
        <mesh
          key={i}
          ref={(el) => (ringsRef.current[i] = el)}
          rotation={[Math.PI / 4, 0, 0]}
        >
          <torusGeometry args={[radius, 0.05, 8, 32]} />
          <meshStandardMaterial
            color="#7b2ff7"
            emissive="#7b2ff7"
            emissiveIntensity={isRunning ? 0.5 : 0.2}
          />
        </mesh>
      ))}

      {/* Connecting Lines */}
      {[-3, 0, 3].map((x, i) => (
        <group key={i}>
          <mesh position={[x, 3, 0]} rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[0.02, 0.02, 3, 8]} />
            <meshStandardMaterial
              color="#00ff88"
              emissive="#00ff88"
              emissiveIntensity={isRunning ? 0.6 : 0.2}
            />
          </mesh>
        </group>
      ))}
    </group>
  )
}

function CentralServer({ partners, globalAccuracy, currentRound, isRunning }) {
  const activePartners = partners.filter((p) => p.dataCount > 0).length

  return (
    <div className="central-server">
      <div className="server-visualization">
        <Canvas camera={{ position: [0, 0, 8] }}>
          <ambientLight intensity={0.3} />
          <pointLight position={[10, 10, 10]} intensity={0.8} />
          <pointLight position={[-10, -10, -10]} intensity={0.4} />

          <ServerCore isRunning={isRunning} />

          <OrbitControls
            enableZoom={false}
            enablePan={false}
            autoRotate={isRunning}
            autoRotateSpeed={2}
          />
        </Canvas>

        {isRunning && (
          <div className="aggregation-indicator">
            <div className="pulse-ring" />
            <span>Aggregating...</span>
          </div>
        )}
      </div>

      <div className="server-stats">
        <div className="stat-card">
          <div className="stat-icon">🌐</div>
          <div className="stat-content">
            <span className="stat-label">Active Partners</span>
            <span className="stat-value">{activePartners}/3</span>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">🔄</div>
          <div className="stat-content">
            <span className="stat-label">Federated Rounds</span>
            <span className="stat-value">{currentRound}</span>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">🎯</div>
          <div className="stat-content">
            <span className="stat-label">Global Accuracy</span>
            <span className="stat-value">
              {(globalAccuracy * 100).toFixed(1)}%
            </span>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">🔐</div>
          <div className="stat-content">
            <span className="stat-label">Privacy Budget</span>
            <span className="stat-value">ε = 0.1</span>
          </div>
        </div>
      </div>

      <div className="aggregation-info">
        <h4>Federated Averaging (FedAvg)</h4>
        <p>
          Securely aggregates encrypted model updates from all partners using weighted
          averaging. Differential privacy (ε=0.1) ensures individual data cannot be
          reconstructed.
        </p>

        <div className="privacy-features">
          <div className="feature">
            <span className="feature-icon">✓</span>
            <span>Homomorphic encryption</span>
          </div>
          <div className="feature">
            <span className="feature-icon">✓</span>
            <span>Differential privacy noise</span>
          </div>
          <div className="feature">
            <span className="feature-icon">✓</span>
            <span>Secure multi-party computation</span>
          </div>
        </div>
      </div>
    </div>
  )
}

export default CentralServer
