import React, { useRef, useEffect, useMemo } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import { OrbitControls, PerspectiveCamera } from '@react-three/drei'
import * as THREE from 'three'

function LiDARPointCloud({ points, color }) {
  const pointsRef = useRef()

  const { positions, colors } = useMemo(() => {
    const positions = new Float32Array(points.length * 3)
    const colors = new Float32Array(points.length * 3)
    const colorObj = new THREE.Color(color)

    points.forEach((point, i) => {
      positions[i * 3] = point.x
      positions[i * 3 + 1] = point.y
      positions[i * 3 + 2] = point.z

      const intensity = point.intensity / 255
      colors[i * 3] = colorObj.r * intensity
      colors[i * 3 + 1] = colorObj.g * intensity
      colors[i * 3 + 2] = colorObj.b * intensity
    })

    return { positions, colors }
  }, [points, color])

  useFrame(() => {
    if (pointsRef.current) {
      pointsRef.current.rotation.y += 0.001
    }
  })

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={positions.length / 3}
          array={positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={colors.length / 3}
          array={colors}
          itemSize={3}
        />
      </bufferGeometry>
      <pointsMaterial
        size={0.05}
        vertexColors
        transparent
        opacity={0.8}
        sizeAttenuation
      />
    </points>
  )
}

function IMUVisualization({ imu, color }) {
  const arrowRef = useRef()

  useFrame(() => {
    if (arrowRef.current && imu) {
      const { x, y, z } = imu.gyroscope
      arrowRef.current.rotation.x += x * 0.1
      arrowRef.current.rotation.y += y * 0.1
      arrowRef.current.rotation.z += z * 0.1
    }
  })

  return (
    <group ref={arrowRef} position={[0, -2, 0]}>
      <mesh>
        <boxGeometry args={[0.5, 0.1, 1]} />
        <meshStandardMaterial color={color} emissive={color} emissiveIntensity={0.3} />
      </mesh>
      <mesh position={[0, 0, 0.7]}>
        <coneGeometry args={[0.3, 0.5, 4]} />
        <meshStandardMaterial color={color} emissive={color} emissiveIntensity={0.5} />
      </mesh>
    </group>
  )
}

function CameraDetections({ features, color }) {
  return (
    <group>
      {features.slice(0, 10).map((feature, i) => {
        const x = ((feature.x / 640) - 0.5) * 10
        const y = ((feature.y / 480) - 0.5) * 7
        const z = -3

        return (
          <mesh key={i} position={[x, y, z]}>
            <sphereGeometry args={[0.1, 8, 8]} />
            <meshStandardMaterial
              color={color}
              emissive={color}
              emissiveIntensity={feature.confidence}
              transparent
              opacity={0.7}
            />
          </mesh>
        )
      })}
    </group>
  )
}

function TactileGrid({ sensors, color }) {
  return (
    <group position={[3, 0, 0]}>
      {sensors.map((sensor, i) => {
        const x = (sensor.x - 1.5) * 0.3
        const y = (sensor.y - 1.5) * 0.3
        const height = sensor.pressure / 100

        return (
          <mesh key={i} position={[x, y, 0]}>
            <boxGeometry args={[0.25, 0.25, height]} />
            <meshStandardMaterial
              color={color}
              emissive={color}
              emissiveIntensity={height}
            />
          </mesh>
        )
      })}
    </group>
  )
}

function Scene({ sensorData, color }) {
  return (
    <>
      {/* Lighting */}
      <ambientLight intensity={0.3} />
      <pointLight position={[10, 10, 10]} intensity={0.5} />
      <pointLight position={[-10, -10, -10]} intensity={0.3} />

      {/* LiDAR Point Cloud */}
      {sensorData.lidar && (
        <LiDARPointCloud points={sensorData.lidar} color={color} />
      )}

      {/* IMU Orientation */}
      {sensorData.imu && (
        <IMUVisualization imu={sensorData.imu} color={color} />
      )}

      {/* Camera Detections */}
      {sensorData.camera && (
        <CameraDetections features={sensorData.camera} color={color} />
      )}

      {/* Tactile Sensors */}
      {sensorData.tactile && sensorData.tactile.sensors && (
        <TactileGrid sensors={sensorData.tactile.sensors} color={color} />
      )}

      {/* Grid Helper */}
      <gridHelper args={[20, 20, color, '#333']} />

      {/* Camera Controls */}
      <PerspectiveCamera makeDefault position={[8, 5, 8]} />
      <OrbitControls
        enableZoom={true}
        enablePan={false}
        minDistance={5}
        maxDistance={20}
        autoRotate
        autoRotateSpeed={0.5}
      />
    </>
  )
}

function SensorVisualization({ sensorData, color, privacyLevel }) {
  return (
    <div style={{ width: '100%', height: '100%' }}>
      <Canvas>
        <Scene sensorData={sensorData} color={color} />
      </Canvas>
    </div>
  )
}

export default SensorVisualization
