import React, { useRef, useEffect } from 'react'
import './ModelMetrics.css'

function ModelMetrics({ roundHistory, currentRound, globalAccuracy }) {
  const canvasRef = useRef(null)

  useEffect(() => {
    if (!canvasRef.current || roundHistory.length === 0) return

    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    const dpr = window.devicePixelRatio || 1

    // Set canvas size
    const rect = canvas.getBoundingClientRect()
    canvas.width = rect.width * dpr
    canvas.height = rect.height * dpr
    ctx.scale(dpr, dpr)

    const width = rect.width
    const height = rect.height
    const padding = 40

    // Clear canvas
    ctx.clearRect(0, 0, width, height)

    // Draw grid
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)'
    ctx.lineWidth = 1

    for (let i = 0; i <= 5; i++) {
      const y = padding + (height - padding * 2) * (i / 5)
      ctx.beginPath()
      ctx.moveTo(padding, y)
      ctx.lineTo(width - padding, y)
      ctx.stroke()
    }

    // Draw axes
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)'
    ctx.lineWidth = 2
    ctx.beginPath()
    ctx.moveTo(padding, padding)
    ctx.lineTo(padding, height - padding)
    ctx.lineTo(width - padding, height - padding)
    ctx.stroke()

    // Draw accuracy line
    if (roundHistory.length > 1) {
      ctx.strokeStyle = '#00d4ff'
      ctx.lineWidth = 3
      ctx.beginPath()

      roundHistory.forEach((round, i) => {
        const x = padding + ((width - padding * 2) * i) / (roundHistory.length - 1)
        const accuracy = round.globalAccuracy || 0.33
        const y = height - padding - ((height - padding * 2) * accuracy)

        if (i === 0) {
          ctx.moveTo(x, y)
        } else {
          ctx.lineTo(x, y)
        }
      })

      ctx.stroke()

      // Draw points
      ctx.fillStyle = '#00d4ff'
      roundHistory.forEach((round, i) => {
        const x = padding + ((width - padding * 2) * i) / (roundHistory.length - 1)
        const accuracy = round.globalAccuracy || 0.33
        const y = height - padding - ((height - padding * 2) * accuracy)

        ctx.beginPath()
        ctx.arc(x, y, 4, 0, Math.PI * 2)
        ctx.fill()
      })
    }

    // Draw labels
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)'
    ctx.font = '12px -apple-system, sans-serif'
    ctx.textAlign = 'right'

    for (let i = 0; i <= 5; i++) {
      const y = padding + (height - padding * 2) * (i / 5)
      const label = ((1 - i / 5) * 100).toFixed(0) + '%'
      ctx.fillText(label, padding - 10, y + 4)
    }

    ctx.textAlign = 'center'
    ctx.fillText('Rounds', width / 2, height - 10)

  }, [roundHistory, currentRound])

  const behaviorClasses = [
    { name: 'Normal Driving', icon: '🚗', accuracy: 0.92 },
    { name: 'Hard Braking', icon: '⚠️', accuracy: 0.88 },
    { name: 'Sharp Turn', icon: '↪️', accuracy: 0.85 },
    { name: 'Lane Change', icon: '↔️', accuracy: 0.90 },
    { name: 'Pedestrian Detection', icon: '🚶', accuracy: 0.87 },
    { name: 'Obstacle Avoidance', icon: '🛑', accuracy: 0.91 },
  ]

  return (
    <div className="model-metrics">
      {/* Chart */}
      <div className="metrics-chart">
        <canvas ref={canvasRef} />
      </div>

      {/* Current Metrics */}
      <div className="current-metrics">
        <div className="metric-highlight">
          <span className="metric-highlight-label">Current Accuracy</span>
          <span className="metric-highlight-value">
            {(globalAccuracy * 100).toFixed(1)}%
          </span>
        </div>

        <div className="metric-highlight">
          <span className="metric-highlight-label">Training Rounds</span>
          <span className="metric-highlight-value">{currentRound}</span>
        </div>

        <div className="metric-highlight">
          <span className="metric-highlight-label">Improvement</span>
          <span className="metric-highlight-value improvement">
            +{((globalAccuracy - 0.33) * 100).toFixed(1)}%
          </span>
        </div>
      </div>

      {/* Per-Class Accuracy */}
      <div className="class-accuracy">
        <h4>Behavior Prediction Accuracy by Class</h4>
        <div className="class-grid">
          {behaviorClasses.map((cls, i) => (
            <div key={i} className="class-item">
              <div className="class-header">
                <span className="class-icon">{cls.icon}</span>
                <span className="class-name">{cls.name}</span>
              </div>
              <div className="class-bar">
                <div
                  className="class-bar-fill"
                  style={{ width: `${cls.accuracy * 100}%` }}
                />
                <span className="class-bar-label">
                  {(cls.accuracy * 100).toFixed(0)}%
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

export default ModelMetrics
