import React from 'react'
import './ControlPanel.css'

function ControlPanel({
  isRunning,
  currentRound,
  globalAccuracy,
  onStart,
  onStop,
  onReset,
  onToggleQuery,
}) {
  return (
    <div className="control-panel">
      <div className="control-content">
        {/* Status Display */}
        <div className="status-display">
          <div className="status-item">
            <span className="status-label">Status:</span>
            <span className={`status-badge ${isRunning ? 'running' : 'stopped'}`}>
              {isRunning ? (
                <>
                  <span className="status-dot pulsing" />
                  Training Active
                </>
              ) : (
                <>
                  <span className="status-dot" />
                  Idle
                </>
              )}
            </span>
          </div>

          <div className="status-item">
            <span className="status-label">Round:</span>
            <span className="status-value">{currentRound}</span>
          </div>

          <div className="status-item">
            <span className="status-label">Accuracy:</span>
            <span className="status-value accuracy">
              {(globalAccuracy * 100).toFixed(1)}%
            </span>
          </div>
        </div>

        {/* Control Buttons */}
        <div className="control-buttons">
          {!isRunning ? (
            <button className="control-btn primary" onClick={onStart}>
              <span className="btn-icon">▶️</span>
              Start Training
            </button>
          ) : (
            <button className="control-btn warning" onClick={onStop}>
              <span className="btn-icon">⏸️</span>
              Pause Training
            </button>
          )}

          <button className="control-btn secondary" onClick={onReset}>
            <span className="btn-icon">🔄</span>
            Reset
          </button>

          <button className="control-btn secondary" onClick={onToggleQuery}>
            <span className="btn-icon">🔍</span>
            Query Data
          </button>
        </div>
      </div>

      {/* Info Banner */}
      <div className="info-banner">
        <div className="banner-icon">ℹ️</div>
        <div className="banner-content">
          <p>
            <strong>Live Federated Learning Simulation:</strong> Each partner trains locally
            on their private data. Only encrypted model gradients are shared with the central
            server for aggregation. Watch as the global model improves without any raw data
            leaving the partner premises.
          </p>
        </div>
      </div>
    </div>
  )
}

export default ControlPanel
